#!/usr/bin/env python3
"""fix_menu_logo.py -- the new Academic Battle Cards logo on the menu and everywhere the old logo/crest appeared.

Run from the repo root:   python3 fix_menu_logo.py
                          python3 build.py
Undo:                     restore src/game.src.html AND assets/assets.json from the .bak files this writes.

WHAT IT DOES
  * Adds the new logo (feathered into the page's paper colour, 640 px WebP) to assets/assets.json and points both the
    menu crest (ABC_CREST) and the small logo (ABC_LOGO) at it. The old images (a110, a107) are removed from the bundle.
  * Menu title page: the logo carries the title, so only the "A LITERARY SCRIMMAGE" tagline stays under it.
  * The logo has no frame or shadow anywhere (it fades into the paper by itself).
"""
import os, sys, re, json, shutil, datetime
CSS_BASE = r"""
/* fix_menu_logo */
.mb-crest{width:min(300px,88%)!important;height:auto!important;aspect-ratio:640/714;margin:-6px auto 2px!important}   /* space reserved: nothing shifts when it loads */
@media (max-width:760px){ .mb-crest{width:min(250px,80%)!important} }
/* the same art everywhere the logo appears: it is feathered into the paper, so no frame or shadow around it */
.title-logo{width:min(300px,80%)!important;height:auto!important;aspect-ratio:640/714;border-radius:0!important;box-shadow:none!important;background:none!important}
.title-logo.sm{width:min(170px,50%)!important}
"""
CSS_A = r"""/* the logo carries the title: the menu keeps only the tagline under it */
.mb-wm .t1,.mb-wm .t2{display:none!important}
.mb-wm .t3{margin-top:4px}
"""
LOGO = ''

SRC=os.path.join('src','game.src.html'); ASSETS=os.path.join('assets','assets.json'); MARK='/* fix_menu_logo */'
OLD='window.ABC_CREST="data:image/jpeg;base64,__ABCASSET_110__";'
OLD_LOGO='window.ABC_LOGO="data:image/jpeg;base64,__ABCASSET_107__";'
def apply(s, assets, TAG, variant='A'):
    if MARK in s: sys.exit(f'{TAG} Already applied -- nothing to do.')
    if '/* fix_menu_book */' not in s: sys.exit(f'{TAG} ERROR: run fix_menu_book.py first. Nothing written.')
    for l,a in [('end of <head> styles',"</style>\n</head>"),('menu crest image',OLD),('small logo image',OLD_LOGO)]:
        if s.count(a)!=1: sys.exit(f'{TAG} ERROR: anchor "{l}" found {s.count(a)} times (expected 1). Nothing written.')
    used={int(x) for x in re.findall(r'__ABCASSET_(\d+)__', s)} | {int(k[1:]) for k in assets if k[1:].isdigit()}
    nid=max(used)+1
    s=s.replace("</style>\n</head>",CSS_BASE+(CSS_A if variant=='A' else '')+"</style>\n</head>",1)
    s=s.replace(OLD,'window.ABC_CREST="data:image/webp;base64,__ABCASSET_%d__";   /* fix_menu_logo: new logo (was a110) */' % nid,1)
    s=s.replace(OLD_LOGO,'window.ABC_LOGO="data:image/webp;base64,__ABCASSET_%d__";   /* fix_menu_logo: new logo (was a107) */' % nid,1)
    for need in [MARK,'window.ABC_LOGO="data:image/webp;base64,__ABCASSET_%d__"' % nid,'window.ABC_CREST="data:image/webp;base64,__ABCASSET_%d__"' % nid]:
        if need not in s: sys.exit(f'{TAG} ERROR: post-check failed ({need}). Nothing written.')
    return s,nid

TAG='[fix_menu_logo]'
if not os.path.exists(SRC): sys.exit(f'{TAG} ERROR: run from the repo root (src/game.src.html not found).')
if not os.path.exists(ASSETS): sys.exit(f'{TAG} ERROR: assets/assets.json not found. Nothing written.')
assets=json.load(open(ASSETS,encoding='utf-8'))
s,nid=apply(open(SRC,encoding='utf-8').read(),assets,TAG,'A')
assets['a%d' % nid]=LOGO
removed=[k for k in ('a110','a107') if '__ABCASSET_%s__' % k[1:] not in s and k in assets]
for k in removed: del assets[k]
missing=set(re.findall(r'__ABCASSET_(\\d+)__', s)) - {k[1:] for k in assets}
if missing: sys.exit(f'{TAG} ERROR: source would reference asset ids not in the bundle: {sorted(missing)[:8]}. Nothing written.')
stamp=datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
shutil.copyfile(SRC,SRC+'.bak_'+stamp); shutil.copyfile(ASSETS,ASSETS+'.bak_'+stamp)
tmp=ASSETS+'.tmp'
with open(tmp,'w',encoding='utf-8') as f: json.dump(assets,f)
open(SRC,'w',encoding='utf-8').write(s); os.replace(tmp,ASSETS)
print(f'{TAG} Applied. New logo in asset slot a{nid}; removed {", ".join(removed) or "nothing"}.'); print(f'{TAG} Backups: {SRC}.bak_{stamp}  {ASSETS}.bak_{stamp}'); print(f'{TAG} Next: python3 build.py')
